<?php
function gm_tabs($selected,$page='order_monitor'){echo '<nav class="gm-tabs" aria-label="'.($page==='outflow'?'Outflow sources':'Monitoring sources').'">';foreach(['Shopee','Lazada','TikTok','Manual'] as $p)echo '<a class="gm-tab '.($p===$selected?'active':'').'"'.($p===$selected?' aria-current="page"':'').' href="?page='.$page.'&platform='.$p.'">'.($p==='Manual'?'Manual Outflow':platform_label($p).' <span>Orders</span>').'</a>';echo '</nav>';}
function gm_badge($s){$class=match($s){'Posted','Delivered','Completed','Resolved'=>'ok','Cancelled','Reversed'=>'info','Missing','Needs Checking','Partially Reversed'=>'danger',default=>'warn'};return '<span class="badge '.$class.'">'.e($s).'</span>';}
function gm_page(){echo '<link rel="stylesheet" href="assets/grouped_monitoring.css?v=5.9.2">';$pl=gm_platform($_GET);$manual=$pl==='Manual';gm_tabs($pl);if(!empty($_GET['manual_id'])){gm_manual_detail((int)$_GET['manual_id'],$_GET['manual_kind']??'batch');return;}$input=$_GET;$input['platform']=$pl;$input['monitor_layout']='grouped';echo '<div class="gm-source"><div><h2>'.e($manual?'Manual Outflow Monitoring':$pl.' Order Monitoring').'</h2><p>'.e($manual?'Track reviewed releases, posted quantities and linked reversals.':om_shops()[$pl].' · Records grouped by fulfillment date.').'</p></div><span class="gm-readonly">Monitoring & history</span></div>';
 if(!$manual)os_exception_panel($pl);$all=gm_records(['platform'=>$pl]);$counts=['All records'=>count($all),'Open for Dispatch'=>0,'Open for Delivery'=>0,'Needs attention'=>0];if($manual)$counts=['All records'=>count($all),'Awaiting Confirmation'=>0,'Posted'=>0,'Needs attention'=>0];$cfg=om_alert_settings();foreach($all as $r){if($manual){if(isset($counts[$r['posting']]))$counts[$r['posting']]++;if(in_array($r['posting'],['Awaiting Confirmation','Partially Reversed'],true))$counts['Needs attention']++;}else{if(in_array($r['platform_status'],['To Ship','Unpaid','Needs Checking'],true)&&$r['posting']!=='Reversed')$counts['Open for Dispatch']++;if($r['platform_status']==='Shipped'&&$r['posting']==='Posted')$counts['Open for Delivery']++;$age=(strtotime(date('Y-m-d'))-strtotime($r['date']))/86400;if($r['exception_text']||$r['monitoring']==='Missing'||($r['monitoring']!=='Resolved'&&$age>=$cfg['high_days']))$counts['Needs attention']++;}}
 echo '<div class="gm-summary">';foreach($counts as $label=>$n){$filter=['page'=>'order_monitor','platform'=>$pl];if($label==='Open for Dispatch')$filter['report_view']='dispatch';if($label==='Open for Delivery')$filter['report_view']='delivery';if($label==='Needs attention')$filter[$manual?'report_view':'attention']='open';if($manual&&in_array($label,['Awaiting Confirmation','Posted'],true))$filter['posting']=$label;echo '<a class="gm-stat '.($label==='Needs attention'&&$n?'attention':'').'" href="?'.e(http_build_query($filter)).'"><span>'.e($label).'</span><strong>'.number_format($n).'</strong></a>';}echo '</div><div class="card"><form method="get"><input type="hidden" name="page" value="order_monitor"><input type="hidden" name="platform" value="'.e($pl).'"><div class="gm-filters"><label>'.($manual?'Reference / Product / SKU':'Order ID / Product / SKU').'<input name="q" value="'.e($input['q']??'').'" placeholder="Search records"></label><label>From Date<input type="date" name="from" value="'.e($input['from']??'').'"></label><label>To Date<input type="date" name="to" value="'.e($input['to']??'').'"></label>';
 if(!$manual)om_select('platform_status','Platform Status',['To Ship','Shipped','Delivered','Completed','Cancelled','Unpaid','Needs Checking','Return / Refund'],$input['platform_status']??'',true);om_select('posting','Inventory Posting',$manual?['Awaiting Confirmation','Posted','Cancelled','Reversed','Partially Reversed']:['Not Posted','Posted','Reversed'],$input['posting']??'',true);if(!$manual){om_select('monitoring','Monitoring',['Needs Follow-up','Missing','Carried Over','Resolved'],$input['monitoring']??'',true);om_select('report_view','View',['all'=>'All Orders','dispatch'=>'Open for Dispatch','delivery'=>'Open for Delivery','open'=>'Open Orders','returns'=>'Return Follow-up','exceptions'=>'Posting / Status Exceptions'],$input['report_view']??'all');om_select('attention','Attention',['open'=>'Needs attention'],$input['attention']??'',true);}else om_select('report_view','View',['all'=>'All Transactions','open'=>'Needs attention'],$input['report_view']??'all');om_select('sort','Date Order',['newest'=>'Newest first','oldest'=>'Oldest first'],$input['sort']??'newest');echo '</div><div class="om-actions gm-right"><a class="btn ghost" href="?page=order_monitor&platform='.e($pl).'">Clear Filters</a><button class="btn primary">Apply Filters</button></div></form></div>';
 $rows=gm_records($input);$size=rs8_page_size('order_monitor');$offset=min(max(0,(int)($_GET['om_offset']??0)),max(0,(int)floor(max(0,count($rows)-1)/$size)*$size));echo '<div class="card gm-register"><div class="gm-list-head"><div><h3>'.($manual?'Manual Releases':'Registered Orders').'</h3><p>'.number_format(count($rows)).' matching records · '.(($input['sort']??'newest')==='oldest'?'Oldest':'Newest').' first</p></div>';om_export_links($input);echo '</div><div class="gm-table"><table class="table" data-server-paginated="1"><thead><tr>';foreach($manual?['Reference / Purpose','Recipient / Quantity','Inventory Posting','Net Physical Effect','Processed By','Action']:['Order / Quantity','Platform Status','Inventory Posting','Monitoring / Age','Last Checked','Responsible','Action'] as $h)echo '<th>'.e($h).'</th>';echo '</tr></thead><tbody>';$last=null;foreach(array_slice($rows,$offset,$size) as $r){if($last!==$r['date']){echo '<tr class="gm-date"><td colspan="'.($manual?6:7).'">'.e(date('l, d F Y',strtotime($r['date']))).'</td></tr>';$last=$r['date'];}$tip=gm_items_text($r['items']);echo '<tr data-record-id="'.$r['id'].'"><td><b>'.e($r['ref']).'</b><div class="muted small">'.e($manual?$r['purpose']:($r['qty'].' product units · '.$r['reserved'].' reserved')).'</div><details><summary class="small">View products</summary><div class="gm-products">'.e($tip?:'See original upload for item details').'</div></details></td>';if($manual)echo '<td>'.e($r['recipient']).'<div class="muted small">'.$r['qty'].' pcs</div></td><td>'.gm_badge($r['posting']).'</td><td><b>'.($r['effect']>0?'+':'').$r['effect'].' pcs</b></td><td>'.e($r['actor']?:'Not recorded').'</td><td><a class="btn ghost sm" href="?page=order_monitor&platform=Manual&manual_kind='.$r['kind'].'&manual_id='.$r['id'].'">View</a></td>';else{$age=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($r['date']))/86400));echo '<td>'.gm_badge($r['platform_status']).'</td><td>'.gm_badge($r['posting']).'</td><td>'.gm_badge($r['monitoring']).'<div class="small '.($age>=$cfg['high_days']&&$r['monitoring']!=='Resolved'?'gm-high':'muted').'">'.($r['monitoring']==='Resolved'?'Resolved':$age.' days open').'</div>'.($r['exception_text']?'<details><summary>Issue</summary>'.e($r['exception_text']).'</details>':'').'</td><td>'.e($r['last_seen_at']??'Never checked').'</td><td>'.e($r['owner_name']?:'Unassigned').'</td><td><a class="btn ghost sm" href="?page=order_monitor&platform='.e($pl).'&order_id='.$r['id'].'">View</a></td>';}echo '</tr>';}if(!$rows)echo '<tr><td colspan="'.($manual?6:7).'">No matching records. Try clearing the filters.</td></tr>';echo '</tbody></table></div>';echo rs8_pagination(count($rows),$offset,$size,$_GET+['platform'=>$pl],'om_offset');echo '<p class="muted small">Exports include all matching records. '.($manual?'A posted release deducts physical stock; a linked reversal offsets its original deduction.':'Registration reserves stock. Confirmed dispatch posts the physical deduction once. Statuses reflect confirmed uploads.').'</p></div>';
}
function gm_manual_detail($id,$kind){$record=null;foreach(gm_manual_records() as $r)if($r['id']===$id&&$r['kind']===$kind){$record=$r;break;}if(!$record)throw new Exception('Manual transaction not found.');$r=$record;echo '<div class="card"><div class="gm-list-head"><div><h2>'.e($r['ref']).'</h2><p>'.e($r['date'].' · '.$r['purpose']).'</p></div>'.gm_badge($r['posting']).'</div><p>Recipient / Business Unit: '.e($r['recipient']).'</p><p>Processed by: '.e($r['actor']).'</p><p><b>Original quantity: '.$r['qty'].' pcs · Net physical effect: '.$r['effect'].' pcs</b></p><div class="om-actions"><a class="btn ghost" href="?page=order_monitor&platform=Manual">All Manual Outflows</a>';if($kind==='batch'&&$r['attachment'])echo '<a class="btn secondary" target="_blank" href="batch_document.php?id='.$id.'">View Attachment</a>';if(access_page_allowed($kind==='batch'?'stock_batch':'outflow_batch'))echo '<a class="btn ghost" href="?page='.($kind==='batch'?'stock_batch&id='.$id:'outflow_batch&id=-'.$id).'">Original Transaction</a>';echo '</div></div><div class="card"><h3>Products</h3>';$products=gm_products();$rows=[];foreach($r['items'] as $pid=>$qty)$rows[]=[$products[$pid]['master_sku']??$pid,$products[$pid]['name']??'Product',$qty];om_table(['Master SKU','Product','Original Quantity'],$rows);echo '</div><div class="card"><h3>Permanent Transaction History</h3>';$rows=[];foreach($r['workflow']['events']??[] as $ev)$rows[]=[$ev['at']??'',$ev['event']??'',$ev['by']['name']??'',$ev['details']??''];foreach($r['lines'] as $l)$rows[]=[$l['created_at'],'Posted release #'.$l['id'],$l['actor'],$l['product_name'].' · '.$l['qty'].' pcs · '.$l['platform']];om_table(['Recorded At','Event','Processed By','Details'],$rows);$reversals=[];foreach($r['lines'] as $l)if(!empty($l['reversed_by_request']))$reversals[(int)$l['reversed_by_request']]=true;foreach(array_keys($reversals) as $rid){echo '<p>Linked reversal request #'.$rid.' — original release retained.</p>';foreach(om_query('SELECT r.*,u.name requester,a.name approver FROM transaction_reversals r LEFT JOIN users u ON u.id=r.requested_by LEFT JOIN users a ON a.id=r.approved_by WHERE r.id=?',[$rid]) as $rev)echo '<p>'.e($rev['status'].' · Requested by '.($rev['requester']?:'Not recorded').' · Approved by '.($rev['approver']?:'Pending').' · '.($rev['approved_at']??'')).'</p><p>Reason: '.e($rev['reason']).'</p>';}if(!$r['attachment'])echo '<p class="muted">No batch attachment recorded.</p>';echo '</div>';}
function gm_processing_page($pl){echo '<link rel="stylesheet" href="assets/order_monitor.css?v=5.9.3"><link rel="stylesheet" href="assets/order_simple.css?v=5.9.3"><div class="om-wrap">';$id=(int)($_GET['upload_id']??0);if($id)om_upload_page($id);elseif(($_GET['entry']??'register')==='history')om_history_page();else om_entry_page(($_GET['entry']??'register')==='status'?'Status':'Register');echo '</div>';}
